/**
 * Generates supabase/migrations/0002_seed.sql from lib/content/seed.ts
 * so the database starts with exactly the demo content shown by the site.
 *
 *   npx tsx scripts/generate-seed-sql.ts
 */
import { writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { seedContent as c } from "../lib/content/seed";

const q = (v: unknown) => `'${String(v).replace(/'/g, "''")}'`;
const j = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;

const lines: string[] = [
  "-- Generated by scripts/generate-seed-sql.ts — do not edit by hand.",
  "-- Idempotent: re-running upserts the same demo rows.",
  "",
];

// Stable UUIDs derived from seed ids so re-runs upsert instead of duplicating.
const uuid = (id: string) => {
  let h = 0;
  for (const ch of id) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  const hex = h.toString(16).padStart(8, "0");
  return `00000000-0000-4000-8000-${hex}0000`;
};

const s = c.settings;
lines.push(`insert into public.site_settings (id, name, tagline, description, founded_year, phone, email, address, hours, map_embed_url, social)
values (1, ${q(s.name)}, ${j(s.tagline)}, ${j(s.description)}, ${s.foundedYear}, ${q(s.phone)}, ${q(s.email)}, ${j(s.address)}, ${j(s.hours)}, ${q(s.mapEmbedUrl)}, ${j(s.social)})
on conflict (id) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description,
  founded_year = excluded.founded_year, phone = excluded.phone, email = excluded.email, address = excluded.address,
  hours = excluded.hours, map_embed_url = excluded.map_embed_url, social = excluded.social;`, "");

for (const h of c.heroSlides) {
  lines.push(`insert into public.hero_slides (id, sort_order, eyebrow, title, image, image_alt)
values (${q(uuid(h.id))}, ${h.sortOrder}, ${j(h.eyebrow)}, ${j(h.title)}, ${q(h.image)}, ${j(h.imageAlt)})
on conflict (id) do update set sort_order = excluded.sort_order, eyebrow = excluded.eyebrow, title = excluded.title, image = excluded.image, image_alt = excluded.image_alt;`);
}
lines.push("");

for (const sec of Object.values(c.sections)) {
  lines.push(`insert into public.sections (key, eyebrow, title, is_enabled)
values (${q(sec.key)}, ${j(sec.eyebrow)}, ${j(sec.title)}, ${sec.isEnabled})
on conflict (key) do update set eyebrow = excluded.eyebrow, title = excluded.title, is_enabled = excluded.is_enabled;`);
}
lines.push("");

const a = c.about;
lines.push(`insert into public.about (id, paragraphs, image_1, image_2, counter_value, counter_label, quote, quote_author)
values (1, ${j(a.paragraphs)}, ${q(a.images[0])}, ${q(a.images[1])}, ${a.counterValue}, ${j(a.counterLabel)}, ${j(a.quote)}, ${q(a.quoteAuthor)})
on conflict (id) do update set paragraphs = excluded.paragraphs, image_1 = excluded.image_1, image_2 = excluded.image_2,
  counter_value = excluded.counter_value, counter_label = excluded.counter_label, quote = excluded.quote, quote_author = excluded.quote_author;`, "");

for (const m of c.team) {
  lines.push(`insert into public.team_members (id, sort_order, name, role, image)
values (${q(uuid(m.id))}, ${m.sortOrder}, ${q(m.name)}, ${j(m.role)}, ${q(m.image)})
on conflict (id) do update set sort_order = excluded.sort_order, name = excluded.name, role = excluded.role, image = excluded.image;`);
}
lines.push("");

for (const cat of c.menuCategories) {
  lines.push(`insert into public.menu_categories (id, slug, sort_order, name)
values (${q(uuid(cat.id))}, ${q(cat.slug)}, ${cat.sortOrder}, ${j(cat.name)})
on conflict (id) do update set slug = excluded.slug, sort_order = excluded.sort_order, name = excluded.name;`);
}
lines.push("");

for (const it of c.menuItems) {
  lines.push(`insert into public.menu_items (id, category_id, sort_order, name, description, price, currency, image, is_available)
values (${q(uuid(it.id))}, ${q(uuid(it.categoryId))}, ${it.sortOrder}, ${j(it.name)}, ${j(it.description)}, ${it.price}, ${q(it.currency)}, ${q(it.image)}, ${it.isAvailable})
on conflict (id) do update set category_id = excluded.category_id, sort_order = excluded.sort_order, name = excluded.name,
  description = excluded.description, price = excluded.price, currency = excluded.currency, image = excluded.image, is_available = excluded.is_available;`);
}
lines.push("");

for (const sv of c.services) {
  lines.push(`insert into public.services (id, sort_order, title, description, image)
values (${q(uuid(sv.id))}, ${sv.sortOrder}, ${j(sv.title)}, ${j(sv.description)}, ${q(sv.image)})
on conflict (id) do update set sort_order = excluded.sort_order, title = excluded.title, description = excluded.description, image = excluded.image;`);
}
lines.push("");

for (const g of c.gallery) {
  lines.push(`insert into public.gallery_images (id, sort_order, image, caption, width, height)
values (${q(uuid(g.id))}, ${g.sortOrder}, ${q(g.image)}, ${j(g.caption)}, ${g.width}, ${g.height})
on conflict (id) do update set sort_order = excluded.sort_order, image = excluded.image, caption = excluded.caption, width = excluded.width, height = excluded.height;`);
}
lines.push("");

for (const p of c.posts) {
  lines.push(`insert into public.posts (id, slug, published_at, title, excerpt, body, cover_image, gallery)
values (${q(uuid(p.id))}, ${q(p.slug)}, ${q(p.publishedAt)}, ${j(p.title)}, ${j(p.excerpt)}, ${j(p.body)}, ${q(p.coverImage)}, ${j(p.gallery)})
on conflict (id) do update set slug = excluded.slug, published_at = excluded.published_at, title = excluded.title,
  excerpt = excluded.excerpt, body = excluded.body, cover_image = excluded.cover_image, gallery = excluded.gallery;`);
}
lines.push("");

const out = resolve(__dirname, "../supabase/migrations/0002_seed.sql");
writeFileSync(out, lines.join("\n"), "utf8");
console.log(`wrote ${out} (${lines.length} lines)`);
